describe('Navigation Menu Active Item Highlighting', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should highlight the active menu item when navigating to a page', () => {
    // Verify initial state - Dashboard should be active
    cy.get('[data-testid="nav-menu-item-dashboard"]').should('have.class', 'active');
    cy.get('[data-testid="nav-menu-item-dashboard"]').should('be.visible');

    // Click on another menu item
    cy.get('[data-testid="nav-menu-item-settings"]').click();

    // Verify Settings is now active
    cy.get('[data-testid="nav-menu-item-settings"]').should('have.class', 'active');
    cy.get('[data-testid="nav-menu-item-settings"]').should('be.visible');

    // Verify Dashboard is no longer active
    cy.get('[data-testid="nav-menu-item-dashboard"]').should('not.have.class', 'active');

    // Navigate back to Dashboard
    cy.get('[data-testid="nav-menu-item-dashboard"]').click();

    // Verify Dashboard is active again
    cy.get('[data-testid="nav-menu-item-dashboard"]').should('have.class', 'active');
    cy.get('[data-testid="nav-menu-item-dashboard"]').should('be.visible');
  });

  it('should handle multiple active menu items and edge cases', () => {
    // Navigate to Settings
    cy.get('[data-testid="nav-menu-item-settings"]').click();
    cy.get('[data-testid="nav-menu-item-settings"]').should('have.class', 'active');

    // Navigate to Profile
    cy.get('[data-testid="nav-menu-item-profile"]').click();
    cy.get('[data-testid="nav-menu-item-profile"]').should('have.class', 'active');
    cy.get('[data-testid="nav-menu-item-settings"]').should('not.have.class', 'active');

    // Edge case: Click on an inactive item that is already active (should not change state)
    cy.get('[data-testid="nav-menu-item-profile"]').click();
    cy.get('[data-testid="nav-menu-item-profile"]').should('have.class', 'active');

    // Edge case: Click on a non-existent or disabled menu item (should not cause error)
    cy.get('[data-testid="nav-menu-item-disabled"]').should('be.disabled');
    cy.get('[data-testid="nav-menu-item-disabled"]').click({ force: true });
    cy.get('[data-testid="nav-menu-item-profile"]').should('have.class', 'active');

    // Verify all other items are not active
    cy.get('[data-testid="nav-menu-item-dashboard"]').should('not.have.class', 'active');
    cy.get('[data-testid="nav-menu-item-settings"]').should('not.have.class', 'active');
  });
});
